fn main() -> Result<(), Box<dyn std::error::Error>> {
    let before = baseline::memory_allowance(Default::default(), Default::default());
    let after = candidate::memory_allowance(Default::default(), Default::default());
    let encode = |status: String, available: Option<u64>, budget: Option<usize>| {
        serde_json::json!({"status": status, "available_bytes": available, "budget_bytes": budget})
    };
    let before = match before {
        Ok(value) => encode("ok".into(), value.available_bytes, Some(value.budget_bytes)),
        Err(error) => encode(error.to_string(), None, None),
    };
    let after = match after {
        Ok(value) => encode("ok".into(), value.available_bytes, Some(value.budget_bytes)),
        Err(error) => encode(error.to_string(), None, None),
    };
    let mut book = baseline::Workbook::new(Default::default())?;
    let id = book.create_sheet("Registry")?;
    book.sheet_mut(id)?.set(baseline::Cell {
        address: baseline::CellAddress::new(0, 0)?,
        value: baseline::CellValue::Integer(7),
        style: baseline::StyleId::new(0),
    })?;
    assert_eq!(book.sheet(id)?.get(baseline::CellAddress::new(0, 0)?).unwrap().value,
        baseline::CellValue::Integer(7));
    println!("{}", serde_json::json!({"baseline":before,"candidate":after,"registry_smoke":"passed"}));
    Ok(())
}
